function parseCSV(t){const rows=[];let r=[],c='',q=false;for(let i=0;i<t.length;i++){const ch=t[i],n=t[i+1];if(ch==='"'){if(q&&n==='"'){c+='"';i++}else q=!q}else if(ch===','&&!q){r.push(c);c=''}else if((ch==='\n'||ch==='\r')&&!q){if(ch==='\r'&&n==='\n')i++;r.push(c);c='';if(r.some(v=>v!==''))rows.push(r);r=[]}else c+=ch}if(c||r.length){r.push(c);if(r.some(v=>v!==''))rows.push(r)}const h=rows.shift()||[];return rows.map(x=>Object.fromEntries(h.map((k,i)=>[k,x[i]??''])))}
